type UvWorkspaceSourceIndicesOpts struct {
	// Merge indices from all workspace members' pyproject.toml files. When True, member-level indices are included alongside workspace-level indices (member entries win on name collision).
	IncludeFromMembers bool
}

// The package indices configured for this workspace.
//
// Reads `[[index]]` from `uv.toml` when present, otherwise falls back
// to `[[tool.uv.index]]` in `pyproject.toml`, matching uv's own
// precedence (`uv.toml` overrides the entire `[tool.uv]` section).
//
// When `include_from_members` is set, also reads `[[tool.uv.index]]`
// from every workspace member's `pyproject.toml` and merges them
// (member entries take precedence on name collision).
func (r *UvWorkspaceSource) Indices(ctx context.Context, opts ...UvWorkspaceSourceIndicesOpts) ([]UvIndex, error) {
	q := r.query.Select("indices")
	for i := len(opts) - 1; i >= 0; i-- {
		// `includeFromMembers` optional argument
		if !querybuilder.IsZeroValue(opts[i].IncludeFromMembers) {
			q = q.Arg("includeFromMembers", opts[i].IncludeFromMembers)
		}
	}

	q = q.Select("id")

	type indices struct {
		Id ID
	}

	convert := func(fields []indices) []UvIndex {
		out := []UvIndex{}

		for i := range fields {
			val := UvIndex{id: &fields[i].Id}
			val.query = selectNode(q.Root(), fields[i].Id, "UvIndex")
			out = append(out, val)
		}

		return out
	}
	var response []indices

	q = q.Bind(&response)

	err := q.Execute(ctx)
	if err != nil {
		return nil, err
	}

	return convert(response), nil
}

